#!/usr/bin/env python3
"""Which keys each category's `type` reads: a wrong-typed value for each key, per category, one session each."""
import subprocess, json, sys
EXE = sys.argv[1] if len(sys.argv) > 1 else '/workspace/executable'
cats = {
    'wall': 'Generic - 200mm', 'floor': 'Generic - 200mm', 'ceiling': 'Generic - 20mm', 'roof': 'Generic - 300mm',
    'door': 'Single 800 x 2100', 'window': 'Fixed 600 x 900', 'column': 'Round 300',
    'structuralcolumn': 'Concrete 300 x 300', 'footing': 'Footing 1200 x 1200', 'railing': 'Railing - 1000mm',
    'beam': 'Beam 150 x 400', 'pipe': 'PVC 50', 'cable': 'Cat6',
}
bad = {'thickness': '"abc"', 'width': '"abc"', 'height': '"abc"', 'sill': '"abc"', 'depth': '"abc"', 'round': '"abc"',
       'material': '5', 'grid': '"abc"', 'spacing': '"abc"', 'operation': '5', 'layers': '5', 'variable': '5', 'function': '5'}
cmds = []
for c, n in cats.items():
    for k, v in bad.items():
        cmds.append((c, k, 'type {"category":"%s","name":"%s","%s":%s}' % (c, n, k, v)))
# one session per command (errors roll back, but run stops at first error), so run separately
res = {}
for c, k, cmd in cmds:
    r = subprocess.run([EXE, 'run', '--cmd', cmd], capture_output=True, timeout=60)
    err = r.stderr.decode().strip()
    res.setdefault(c, {})[k] = 'E' if err else '.'
print('%-18s' % '', ' '.join('%-9s' % k[:9] for k in bad))
for c in cats:
    print('%-18s' % c, ' '.join('%-9s' % res[c][k] for k in bad))

