#!/usr/bin/env python3
import json, subprocess, os
os.chdir('/tmp/types-agent/w')
for l in ['en', 'pt', 'es', 'sv', 'cs', 'fr', 'nl', 'de', 'it']:
    r = subprocess.run(['/workspace/executable', 'run', '--cmd', 'new {"language":"%s"}' % l, '--save', 'lang_%s.bimcraft' % l],
                       capture_output=True)
    if r.returncode:
        print(l, r.stderr.decode().strip())
        continue
    d = json.load(open('lang_%s.bimcraft' % l))
    t = d['types']
    out = {}
    for c in t:
        if c == 'runs':
            for rr in t[c]:
                out[rr] = list(t[c][rr])
        else:
            out[c] = list(t[c])
    print(l, json.dumps(out, ensure_ascii=False))

