#!/usr/bin/env python3
"""Which `types` categories a file must have, and what saving one without them writes."""
import json, subprocess, tempfile, os, shutil, copy
base = json.load(open('/tmp/types-agent/w/base.bimcraft'))
keys = list(base['types'].keys()) + ['runs.' + k for k in base['types']['runs']]
for k in keys:
    d = copy.deepcopy(base)
    if k.startswith('runs.'):
        del d['types']['runs'][k[5:]]
    else:
        del d['types'][k]
    tmp = tempfile.mkdtemp()
    json.dump(d, open(os.path.join(tmp, 'x.bimcraft'), 'w'), indent=2)
    r = subprocess.run(['/workspace/executable', 'run', 'x.bimcraft', '--cmd', 'level {"name":"Q","elevation":7000}', '--save', 'y.bimcraft'], cwd=tmp, capture_output=True)
    if r.returncode:
        print('%-22s ERR %s' % (k, r.stderr.decode().strip()))
    else:
        y = json.load(open(os.path.join(tmp, 'y.bimcraft')))
        t = y['types']
        print('%-22s ok: types keys %s runs %s' % (k, list(t.keys()), list(t.get('runs', {}).keys())))
    shutil.rmtree(tmp)
# empty categories
for k in ['wall', 'floor', 'door', 'column', 'railing', 'structural_column', 'runs', 'runs.beam']:
    d = copy.deepcopy(base)
    if k.startswith('runs.'):
        d['types']['runs'][k[5:]] = {}
    else:
        d['types'][k] = {}
    tmp = tempfile.mkdtemp()
    json.dump(d, open(os.path.join(tmp, 'x.bimcraft'), 'w'), indent=2)
    r = subprocess.run(['/workspace/executable', 'run', 'x.bimcraft', '--cmd', 'level {"name":"Q","elevation":7000}', '--save', 'y.bimcraft'], cwd=tmp, capture_output=True)
    if r.returncode:
        print('empty %-16s ERR %s' % (k, r.stderr.decode().strip()))
    else:
        y = json.load(open(os.path.join(tmp, 'y.bimcraft')))
        t = y['types']
        print('empty %-16s ok: types keys %s runs %s; %s' % (k, list(t.keys()), list(t.get('runs', {}).keys()), json.dumps(t.get(k.replace('runs.', ''), t.get('runs', {}).get(k[5:])))[:200]))
    shutil.rmtree(tmp)

