//! A type's layers as `type {layers}` gives them: read field by field as the original reads its
//! `Layer` (serde, from a JSON value), with its defaults and its very errors; and as the file and
//! the replies hold them.

use crate::json::{fmt_f64, Map, Num, Value};
use crate::structure::members::read::parse_guid;

/// A layer's function, in the order the original lists them.
pub const FUNCTIONS: &[&str] = &["structure", "substrate", "thermal", "membrane", "finish"];

/// The most layers a type has.
pub const MAX_LAYERS: usize = 32;

/// What a part's `guid` names: a GUID, or (as a command may give it) an element's id; id 0 is none.
#[derive(Clone, Debug, PartialEq)]
pub enum GRef {
    Guid(String),
    Id(u64),
}

impl GRef {
    pub fn is_none(&self) -> bool {
        matches!(self, GRef::Id(0))
    }
    pub fn value(&self) -> Value {
        match self {
            GRef::Guid(g) => Value::s(g),
            GRef::Id(n) => Value::u(*n),
        }
    }
}

/// A layer of a wall, floor, roof or ceiling type, as the original holds it: its material by
/// name ("" for none).
#[derive(Clone, Debug, PartialEq)]
pub struct Layer {
    /// Its part id; None (0) until it has one.
    pub id: Option<u64>,
    pub guid: Option<GRef>,
    pub function: String,
    pub material: String,
    pub thickness: f64,
    pub variable: bool,
}

impl Layer {
    pub fn has_ref(&self) -> bool {
        self.id.is_some() || self.guid.is_some()
    }
    /// As replies and `inspect` show it: keys sorted, its material by name, its id and GUID
    /// where it has them.
    pub fn view(&self) -> Value {
        let mut m = Map::new();
        m.insert("function", Value::s(&self.function));
        if let Some(g) = &self.guid {
            m.insert("guid", g.value());
        }
        if let Some(id) = self.id {
            m.insert("id", Value::u(id));
        }
        m.insert("material", Value::s(&self.material));
        m.insert("thickness", Value::f(self.thickness));
        if self.variable {
            m.insert("variable", Value::Bool(true));
        }
        Value::Obj(m)
    }
}

/// A GUID as the original takes one (hyphenated, maybe in braces, any case): one whose first
/// 64 bits are all zero is how it writes an element's id, so not a GUID.
pub fn real_guid(s: &str) -> Option<String> {
    let g = parse_guid(s)?;
    let hi: String = g.chars().filter(|c| *c != '-').take(16).collect();
    if hi.bytes().all(|b| b == b'0') {
        None
    } else {
        Some(g)
    }
}

// ---------------------------------------------------------------- serde's wording

/// A value as serde_json names it in "invalid type" errors.
pub fn unexpected(v: &Value) -> String {
    match v {
        Value::Null => "null".into(),
        Value::Bool(b) => format!("boolean `{}`", b),
        Value::Num(Num::U(u)) => format!("integer `{}`", u),
        Value::Num(Num::I(i)) => format!("integer `{}`", i),
        Value::Num(Num::F(f)) => format!("floating point `{}`", fmt_f64(*f)),
        Value::Str(s) => format!("string {:?}", s),
        Value::Arr(_) => "sequence".into(),
        Value::Obj(_) => "map".into(),
    }
}

fn invalid(v: &Value, what: &str) -> String {
    format!("invalid type: {}, expected {}", unexpected(v), what)
}

fn de_u64(v: &Value) -> Result<u64, String> {
    match v {
        Value::Num(Num::U(u)) => Ok(*u),
        Value::Num(Num::I(i)) => Err(format!("invalid value: integer `{}`, expected u64", i)),
        _ => Err(invalid(v, "u64")),
    }
}

fn de_f64(v: &Value) -> Result<f64, String> {
    match v {
        Value::Num(n) => Ok(n.as_f64()),
        _ => Err(invalid(v, "f64")),
    }
}

fn de_bool(v: &Value) -> Result<bool, String> {
    match v {
        Value::Bool(b) => Ok(*b),
        _ => Err(invalid(v, "a boolean")),
    }
}

fn de_string(v: &Value) -> Result<String, String> {
    match v {
        Value::Str(s) => Ok(s.clone()),
        _ => Err(invalid(v, "a string")),
    }
}

fn unknown_variant(s: &str) -> String {
    let list: Vec<String> = FUNCTIONS.iter().map(|f| format!("`{}`", f)).collect();
    format!("unknown variant `{}`, expected one of {}", s, list.join(", "))
}

/// A layer's `function`: a unit variant, by name or as a map of one key.
fn de_function(v: &Value) -> Result<String, String> {
    match v {
        Value::Str(s) => {
            if FUNCTIONS.contains(&s.as_str()) {
                Ok(s.clone())
            } else {
                Err(unknown_variant(s))
            }
        }
        Value::Obj(m) => {
            if m.len() != 1 {
                return Err("invalid value: map, expected map with a single key".into());
            }
            let (k, x) = &m.items[0];
            if !FUNCTIONS.contains(&k.as_str()) {
                return Err(unknown_variant(k));
            }
            match x {
                Value::Null => Ok(k.clone()),
                other => Err(invalid(other, "unit")),
            }
        }
        _ => Err(invalid(v, "string or map")),
    }
}

/// A part's `guid`: a GUID, or an element's id (a whole number, or one in a string).
pub fn de_ref(v: &Value) -> Result<GRef, String> {
    match v {
        Value::Str(s) => {
            if let Some(g) = real_guid(s) {
                return Ok(GRef::Guid(g));
            }
            let t = s.trim();
            if !t.is_empty() && t.bytes().all(|b| b.is_ascii_digit()) {
                if let Ok(n) = t.parse::<u64>() {
                    return Ok(GRef::Id(n));
                }
            }
            Err(format!("`{}` is not a GUID (xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx) or an id", s))
        }
        Value::Num(Num::U(u)) => Ok(GRef::Id(*u)),
        Value::Num(Num::I(i)) => Err(format!("{} is not an element id", i)),
        Value::Num(Num::F(f)) => {
            if *f >= 0.0 && f.fract() == 0.0 && *f < 18446744073709551616.0 {
                Ok(GRef::Id(*f as u64))
            } else {
                Err(format!("{} is not an element id", f))
            }
        }
        _ => Err(invalid(v, "an element's GUID, or its id")),
    }
}

const FIELDS: &[&str] = &["id", "guid", "function", "material", "thickness", "variable"];

/// One layer of `layers`, as serde reads the original's `Layer` from a JSON value: a map (its
/// keys in order, as serde_json's map holds them; no others) or a sequence of its fields.
pub fn de_layer(v: &Value) -> Result<Layer, String> {
    let mut l = Layer {
        id: None,
        guid: None,
        function: "structure".into(),
        material: String::new(),
        thickness: 0.0,
        variable: false,
    };
    match v {
        Value::Obj(m) => {
            let mut keys: Vec<&String> = m.keys().collect();
            keys.sort();
            keys.dedup();
            let mut thickness = None;
            for k in keys {
                let x = m.get(k).unwrap();
                match k.as_str() {
                    "id" => l.id = Some(de_u64(x)?),
                    "guid" => l.guid = Some(de_ref(x)?),
                    "function" => l.function = de_function(x)?,
                    "material" => l.material = de_string(x)?,
                    "thickness" => thickness = Some(de_f64(x)?),
                    "variable" => l.variable = de_bool(x)?,
                    other => {
                        let list: Vec<String> = FIELDS.iter().map(|f| format!("`{}`", f)).collect();
                        return Err(format!("unknown field `{}`, expected one of {}", other, list.join(", ")));
                    }
                }
            }
            l.thickness = thickness.ok_or_else(|| "missing field `thickness`".to_string())?;
        }
        Value::Arr(a) => {
            let mut it = a.iter();
            if let Some(x) = it.next() {
                l.id = Some(de_u64(x)?);
            }
            if let Some(x) = it.next() {
                l.guid = Some(de_ref(x)?);
            }
            if let Some(x) = it.next() {
                l.function = de_function(x)?;
            }
            if let Some(x) = it.next() {
                l.material = de_string(x)?;
            }
            match it.next() {
                Some(x) => l.thickness = de_f64(x)?,
                None => return Err("invalid length 4, expected struct Layer with 6 elements".into()),
            }
            if let Some(x) = it.next() {
                l.variable = de_bool(x)?;
            }
            if a.len() > FIELDS.len() {
                return Err(format!("invalid length {}, expected fewer elements in array", a.len()));
            }
        }
        _ => return Err(invalid(v, "struct Layer")),
    }
    // id 0 and guid 0 are none
    if l.id == Some(0) {
        l.id = None;
    }
    if l.guid.as_ref().map(|g| g.is_none()).unwrap_or(false) {
        l.guid = None;
    }
    Ok(l)
}

/// A command's `layers`: None when not given (or null), else at most 32 layers.
pub fn param(p: &Value, cmd: &str) -> Result<Option<Vec<Layer>>, String> {
    match p.get("layers") {
        None | Some(Value::Null) => Ok(None),
        Some(Value::Arr(a)) if a.len() <= MAX_LAYERS => {
            let mut out = Vec::with_capacity(a.len());
            for x in a {
                out.push(de_layer(x).map_err(|e| format!("{}: `layers`: {}", cmd, e))?);
            }
            Ok(Some(out))
        }
        Some(_) => Err(format!("{}: `layers` is a list of at most {} layers", cmd, MAX_LAYERS)),
    }
}

// ---------------------------------------------------------------- the file's form

/// A layer as the file holds it, read back: its material as the file names it (a GUID, or
/// a name a hand-made file may hold), resolved by `mat`.
pub fn from_file(v: &Value, mat: &dyn Fn(&str) -> String) -> Layer {
    let id = v.get("id").and_then(|x| x.as_u64()).filter(|n| *n != 0);
    let guid = match v.get("guid") {
        Some(Value::Str(s)) => Some(GRef::Guid(s.clone())),
        Some(Value::Num(Num::U(n))) if *n != 0 => Some(GRef::Id(*n)),
        _ => None,
    };
    let material = match v.get("material").and_then(|m| m.as_str()) {
        Some(m) if !m.is_empty() => mat(m),
        _ => String::new(),
    };
    Layer {
        id,
        guid,
        function: v.get("function").and_then(|f| f.as_str()).unwrap_or("structure").to_string(),
        material,
        thickness: v.get("thickness").and_then(|x| x.as_f64()).unwrap_or(0.0),
        variable: v.get("variable").and_then(|x| x.as_bool()).unwrap_or(false),
    }
}

/// A layer as the file holds it: id, guid, function, its material's GUID (or "" for none),
/// thickness, and `variable` when it is.
pub fn to_file(l: &Layer, material_ref: &str) -> Value {
    let mut m = Map::new();
    if let Some(id) = l.id {
        m.insert("id", Value::u(id));
    }
    if let Some(g) = &l.guid {
        m.insert("guid", g.value());
    }
    m.insert("function", Value::s(&l.function));
    m.insert("material", Value::s(material_ref));
    m.insert("thickness", Value::f(l.thickness));
    if l.variable {
        m.insert("variable", Value::Bool(true));
    }
    Value::Obj(m)
}

//! A type as the original holds it, per category: its fields with their defaults, as the file
//! writes them (field order, materials by GUID), as replies show them (keys sorted, materials by
//! name), and the model's rules on it, in the order the original checks them.

use super::layers::{self, real_guid, Layer, MAX_LAYERS};
use crate::commands::params::MAX_MM;
use crate::json::{Map, Value};
use crate::project::Project;
use crate::structure::common::R;

/// The shape of a category's types.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Shape {
    /// Wall, floor, roof, ceiling: a thickness, maybe layers (a ceiling: and a grid).
    Layered,
    /// Door, window: an opening's width and height, its sill, how it operates.
    Opening,
    /// Column, structural column, footing: a section.
    Column,
    /// Beam, strip footing and the MEP runs: a section and a material.
    Run,
    /// Railing: the rail's height and the balusters' spacing.
    Railing,
}

pub fn shape(cat: &str) -> Option<Shape> {
    Some(match cat {
        "wall" | "floor" | "roof" | "ceiling" => Shape::Layered,
        "door" | "window" => Shape::Opening,
        "column" | "structuralcolumn" | "footing" => Shape::Column,
        "railing" => Shape::Railing,
        c if crate::structure::common::is_run(c) => Shape::Run,
        _ => return None,
    })
}

/// How the original names a category's types in its messages.
pub fn word(cat: &str) -> &str {
    match cat {
        "structuralcolumn" => "structural column",
        c => c,
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum Spec {
    Layered { thickness: f64, grid: Option<f64>, layers: Vec<Layer> },
    Opening { width: f64, height: f64, sill: f64, operation: Option<String> },
    Column { width: f64, depth: f64, round: bool },
    Run { width: f64, depth: f64, round: bool, material: Option<String> },
    Railing { height: f64, spacing: f64 },
}

fn num(v: &Value, k: &str) -> f64 {
    v.get(k).and_then(|x| x.as_f64()).unwrap_or(0.0)
}

/// A material reference as the file holds it (its GUID; or a name, from a hand-made file): the
/// material's name, else the reference itself.
pub fn material_name(pr: &Project, r: &str) -> String {
    if let Some(g) = crate::structure::members::read::parse_guid(r) {
        if let Some(id) = crate::structure::members::read::lib_by_guid(pr, &g) {
            let e = &pr.library[&id];
            if e.get("kind").and_then(|k| k.as_str()) == Some("material") {
                if let Some(n) = e.get("name").and_then(|n| n.as_str()) {
                    return n.to_string();
                }
            }
        }
    }
    r.to_string()
}

/// Whether the library has a material of this name.
pub fn has_material(pr: &Project, name: &str) -> bool {
    pr.section("materials").map(|m| m.contains(name)).unwrap_or(false)
}

impl Spec {
    /// A type as the file holds it, its materials by name.
    pub fn from_file(pr: &Project, cat: &str, v: &Value) -> Option<Spec> {
        let mat = |r: &str| material_name(pr, r);
        Some(match shape(cat)? {
            Shape::Layered => Spec::Layered {
                thickness: num(v, "thickness"),
                grid: if cat == "ceiling" { Some(num(v, "grid")) } else { None },
                layers: v
                    .get("layers")
                    .and_then(|l| l.as_arr())
                    .map(|a| a.iter().map(|x| layers::from_file(x, &mat)).collect())
                    .unwrap_or_default(),
            },
            Shape::Opening => Spec::Opening {
                width: num(v, "width"),
                height: num(v, "height"),
                sill: num(v, "sill"),
                operation: v.get("operation").and_then(|o| o.as_str()).map(|s| s.to_string()),
            },
            Shape::Column => Spec::Column {
                width: num(v, "width"),
                depth: num(v, "depth"),
                round: v.get("round").and_then(|r| r.as_bool()).unwrap_or(false),
            },
            Shape::Run => Spec::Run {
                width: num(v, "width"),
                depth: num(v, "depth"),
                round: v.get("round").and_then(|r| r.as_bool()).unwrap_or(false),
                material: v.get("material").and_then(|m| m.as_str()).filter(|m| !m.is_empty()).map(mat),
            },
            Shape::Railing => Spec::Railing { height: num(v, "height"), spacing: num(v, "spacing") },
        })
    }

    /// As the file holds it: fields in the original's order, materials by their GUIDs
    /// (`material_ref` gives a material's from its name).
    pub fn to_file(&self, material_ref: &dyn Fn(&str) -> String) -> Value {
        let mut m = Map::new();
        match self {
            Spec::Layered { thickness, grid, layers } => {
                m.insert("thickness", Value::f(*thickness));
                if let Some(g) = grid {
                    m.insert("grid", Value::f(*g));
                }
                if !layers.is_empty() {
                    let ls: Vec<Value> = layers
                        .iter()
                        .map(|l| {
                            let r = if l.material.is_empty() { String::new() } else { material_ref(&l.material) };
                            layers::to_file(l, &r)
                        })
                        .collect();
                    m.insert("layers", Value::Arr(ls));
                }
            }
            Spec::Opening { width, height, sill, operation } => {
                m.insert("width", Value::f(*width));
                m.insert("height", Value::f(*height));
                m.insert("sill", Value::f(*sill));
                if let Some(o) = operation {
                    m.insert("operation", Value::s(o));
                }
            }
            Spec::Column { width, depth, round } => {
                m.insert("width", Value::f(*width));
                m.insert("depth", Value::f(*depth));
                m.insert("round", Value::Bool(*round));
            }
            Spec::Run { width, depth, round, material } => {
                m.insert("width", Value::f(*width));
                m.insert("depth", Value::f(*depth));
                m.insert("round", Value::Bool(*round));
                if let Some(n) = material {
                    m.insert("material", Value::s(&material_ref(n)));
                }
            }
            Spec::Railing { height, spacing } => {
                m.insert("height", Value::f(*height));
                m.insert("spacing", Value::f(*spacing));
            }
        }
        Value::Obj(m)
    }

    /// As replies show it: keys sorted, materials by name. `fresh` says which layers this
    /// command made (shown without the id and GUID they get after it).
    pub fn view(&self, fresh: &[bool]) -> Value {
        let mut m = Map::new();
        match self {
            Spec::Layered { thickness, grid, layers } => {
                if let Some(g) = grid {
                    m.insert("grid", Value::f(*g));
                }
                if !layers.is_empty() {
                    let ls: Vec<Value> = layers
                        .iter()
                        .enumerate()
                        .map(|(i, l)| {
                            if fresh.get(i).copied().unwrap_or(false) {
                                let mut x = l.clone();
                                x.id = None;
                                x.guid = None;
                                x.view()
                            } else {
                                l.view()
                            }
                        })
                        .collect();
                    m.insert("layers", Value::Arr(ls));
                }
                m.insert("thickness", Value::f(*thickness));
            }
            Spec::Opening { width, height, sill, operation } => {
                m.insert("height", Value::f(*height));
                if let Some(o) = operation {
                    m.insert("operation", Value::s(o));
                }
                m.insert("sill", Value::f(*sill));
                m.insert("width", Value::f(*width));
            }
            Spec::Column { width, depth, round } => {
                m.insert("depth", Value::f(*depth));
                m.insert("round", Value::Bool(*round));
                m.insert("width", Value::f(*width));
            }
            Spec::Run { width, depth, round, material } => {
                m.insert("depth", Value::f(*depth));
                if let Some(n) = material {
                    m.insert("material", Value::s(n));
                }
                m.insert("round", Value::Bool(*round));
                m.insert("width", Value::f(*width));
            }
            Spec::Railing { height, spacing } => {
                m.insert("height", Value::f(*height));
                m.insert("spacing", Value::f(*spacing));
            }
        }
        Value::Obj(m)
    }
}

// ---------------------------------------------------------------- the rules

/// Numbers as the original's messages show them (Rust's Display).
fn d(x: f64) -> String {
    format!("{}", x)
}

fn usable(x: f64) -> bool {
    x.is_finite() && x.abs() <= MAX_MM
}

/// A size: usable, and above zero.
fn size(w: &str, name: &str, field: &str, x: f64) -> R<()> {
    if !usable(x) {
        return Err(format!("{} type `{}` {}: {} is not a usable number", w, name, field, d(x)));
    }
    if x <= 0.0 {
        return Err(format!("{} type `{}` {} must be above zero, got {}", w, name, field, d(x)));
    }
    Ok(())
}

/// The largest a layer's thickness and their sum may differ, mm.
pub const SUM_TOL: f64 = 1e-6;

/// The model's rules on one type, in the original's order; `materials` says whether the
/// library has a material of a name.
pub fn validate(cat: &str, name: &str, t: &Spec, has_mat: &dyn Fn(&str) -> bool) -> R<()> {
    let w = word(cat);
    match t {
        Spec::Opening { width, height, sill, .. } => {
            size(w, name, "width", *width)?;
            size(w, name, "height", *height)?;
            if !usable(*sill) {
                return Err(format!("{} type `{}` sill: {} is not a usable number", w, name, d(*sill)));
            }
        }
        Spec::Layered { thickness, grid, layers } => {
            size(w, name, "thickness", *thickness)?;
            if layers.len() > MAX_LAYERS {
                return Err(format!("{} type `{}`: more than {} layers", w, name, MAX_LAYERS));
            }
            for (i, l) in layers.iter().enumerate() {
                if !l.material.is_empty() && !has_mat(&l.material) {
                    return Err(format!(
                        "{} type `{}` layer {}: material `{}` isn't in the library; add it with `material`",
                        w,
                        name,
                        i + 1,
                        l.material
                    ));
                }
                size(w, name, &format!("layer {} thickness", i + 1), l.thickness)?;
            }
            let variable = layers.iter().filter(|l| l.variable).count();
            if variable > 0 && (cat == "wall" || cat == "ceiling") {
                return Err(format!(
                    "{} type `{}`: only a floor's or a roof's layer can be variable, to take up a shaped top's falls",
                    w, name
                ));
            }
            if variable > 1 {
                return Err(format!(
                    "{} type `{}`: {} variable layers; a type has one variable layer at most",
                    w, name, variable
                ));
            }
            if !layers.is_empty() {
                let sum = layers_sum(layers);
                if (sum - thickness).abs() > SUM_TOL {
                    return Err(format!(
                        "{} type `{}`: its layers add up to {} mm, not its thickness, {} mm",
                        w,
                        name,
                        d(sum),
                        d(*thickness)
                    ));
                }
            }
            if let Some(g) = grid {
                if !(*g == 0.0 || (*g >= 100.0 && *g <= MAX_MM)) {
                    return Err(format!(
                        "{} type `{}`: grid {} mm; its tiles are 100 mm or wider, or 0 for none",
                        w,
                        name,
                        d(*g)
                    ));
                }
            }
        }
        Spec::Column { width, depth, .. } => {
            size(w, name, "width", *width)?;
            size(w, name, "depth", *depth)?;
        }
        Spec::Run { width, depth, round, material } => {
            size(w, name, "width", *width)?;
            size(w, name, "depth", *depth)?;
            if *round && depth != width {
                return Err(format!(
                    "{} type `{}`: a round section is as deep as it is wide ({} mm), not {} mm",
                    w,
                    name,
                    d(*width),
                    d(*depth)
                ));
            }
            if let Some(m) = material {
                if !has_mat(m) {
                    return Err(format!(
                        "{} type `{}`: material `{}` isn't in the library; add it with `material`",
                        w, name, m
                    ));
                }
            }
        }
        Spec::Railing { height, spacing } => {
            size(w, name, "height", *height)?;
            if !(*spacing == 0.0 || (*spacing >= 50.0 && *spacing <= MAX_MM)) {
                return Err(format!(
                    "{} type `{}`: spacing {} mm; balusters stand 50 mm apart or more, or 0 for none",
                    w,
                    name,
                    d(*spacing)
                ));
            }
        }
    }
    if real_guid(name).is_some() {
        return Err(format!("{} type `{}`: a name isn't a GUID; name it otherwise", w, name));
    }
    Ok(())
}

/// What a type's layers add up to, mm.
pub fn layers_sum(layers: &[Layer]) -> f64 {
    let mut s = 0.0;
    for l in layers {
        s += l.thickness;
    }
    s
}

//! `type`: Edit Type for every category, and the type each category uses by default.
//!
//! A category's types live in the file's `types` (`types_path`), each by name, with a library
//! entry `type:<category>` (its GUID, which elements name it by). A wall type may have layers
//! from its exterior side in, a floor's, roof's or ceiling's from the top down; each layer is a
//! part with its own id (counting down with the library's) and GUID, its material by GUID.

