#!/usr/bin/env python3
"""Random `type` commands (and sequences of them), original vs mine through cmp.py.
usage: fuzz.py N [seed]"""
import random, json, subprocess, sys, os
MINE = os.environ.get('MINE', '/workspace/.claude/worktrees/agent-a7400d716490ebdc5/target/release/bimcraft-cli')
N = int(sys.argv[1]) if len(sys.argv) > 1 else 100
seed = int(sys.argv[2]) if len(sys.argv) > 2 else 1
rnd = random.Random(seed)
CATS = ['wall', 'floor', 'ceiling', 'roof', 'door', 'window', 'railing', 'column', 'structuralcolumn', 'footing',
        'beam', 'stripfooting', 'pipe', 'duct', 'conduit', 'cabletray', 'wire', 'downconductor', 'groundconductor', 'cable']
ODD = ['Walls', 'structural column', 'Cable Tray', 'strip_footing', 'foo', 'mass', '', 'DOORS', 'Ceilings']
EXISTING = {
    'wall': ['Exterior - 300mm', 'Generic - 200mm', 'Interior - 100mm'], 'floor': ['Generic - 200mm'],
    'roof': ['Generic - 300mm'], 'ceiling': ['Generic - 20mm', 'Tile 600 x 600'],
    'door': ['Single 800 x 2100', 'Single 900 x 2100'], 'window': ['Fixed 1200 x 1500', 'Fixed 600 x 900'],
    'railing': ['Railing - 1000mm'], 'column': ['Rectangular 400 x 400', 'Round 300'],
    'structuralcolumn': ['Concrete 200 x 500', 'Concrete 300 x 300', 'Concrete Round 400'],
    'footing': ['Footing 1200 x 1200'], 'beam': ['Beam 150 x 400', 'Beam 200 x 500', 'Steel Tube 150'],
    'stripfooting': ['Strip 600 x 300'], 'pipe': ['PVC 50', 'Copper 22'], 'duct': ['Round 300', 'Rectangular 400 x 300'],
    'conduit': ['PVC 25'], 'cabletray': ['Perforated 100 x 50'], 'wire': ['Wire 2.5'], 'downconductor': ['Steel 8'],
    'groundconductor': ['Copper 9'], 'cable': ['Cat6'],
}
MATS = ['Concrete', 'Brick', 'Metal', 'Copper', 'PVC', 'Plaster', 'Insulation', 'Nope', '', 'concrete']
FUNCS = ['structure', 'substrate', 'thermal', 'membrane', 'finish', 'bogus']


def num():
    r = rnd.random()
    if r < 0.55:
        return rnd.choice([10, 20, 50, 100, 150, 200, 250, 300, 600, 900, 1200, 2100, 12.5, 0.5, 75.25])
    if r < 0.65:
        return 0
    if r < 0.72:
        return -rnd.choice([1, 10, 100])
    if r < 0.77:
        return rnd.choice([1e9, 1e10, 2e9])
    if r < 0.85:
        return rnd.choice(['100', None, True, [1], {}])
    return round(rnd.uniform(0.1, 3000), rnd.choice([0, 1, 2, 3]))


def layer():
    l = {}
    if rnd.random() < 0.95:
        l['thickness'] = num() if rnd.random() < 0.3 else rnd.choice([10, 15, 20, 50, 100, 140, 200, 12.5])
    if rnd.random() < 0.7:
        l['function'] = rnd.choice(FUNCS if rnd.random() < 0.2 else FUNCS[:5])
    if rnd.random() < 0.5:
        l['material'] = rnd.choice(MATS)
    if rnd.random() < 0.1:
        l['variable'] = rnd.choice([True, False])
    if rnd.random() < 0.03:
        l['foo'] = 1
    if rnd.random() < 0.03:
        return rnd.choice([5, None, 'x', []])
    return l


def cmd():
    p = {}
    c = rnd.choice(CATS) if rnd.random() < 0.93 else rnd.choice(ODD)
    p['category'] = c
    key = c if c in EXISTING else None
    if rnd.random() < 0.97:
        if key and rnd.random() < 0.5:
            p['name'] = rnd.choice(EXISTING[key])
        else:
            p['name'] = rnd.choice(['X', 'New type', 'A', 'zz', 'X'])
    for k in ['thickness', 'width', 'height', 'sill', 'depth', 'grid', 'spacing']:
        if rnd.random() < 0.25:
            p[k] = num()
    if rnd.random() < 0.2:
        p['round'] = rnd.choice([True, False, True, 'yes', None])
    if rnd.random() < 0.2:
        p['material'] = rnd.choice(MATS + [5])
    if rnd.random() < 0.15:
        p['operation'] = rnd.choice(['swing', 'double-swing', 'sliding', 'Fixed', '', 'bogus', 5, None])
    if rnd.random() < (0.5 if c in ('wall', 'floor', 'roof', 'ceiling') else 0.08):
        n = rnd.choice([0, 1, 1, 2, 2, 3, 4])
        p['layers'] = [layer() for _ in range(n)]
    return 'type ' + json.dumps(p, ensure_ascii=False)


fails = 0
for i in range(N):
    seq = [cmd() for _ in range(rnd.choice([1, 1, 2, 3]))]
    args = ['run']
    for c in seq:
        args += ['--cmd', c]
    args += ['--save', 'out.bimcraft']
    r = subprocess.run(['python3', '/tmp/tools/cmp.py', '--'] + args, capture_output=True, env=dict(os.environ, MINE=MINE))
    out = r.stdout.decode()
    if not out.strip().endswith('SAME'):
        fails += 1
        print('FAIL', ' ;; '.join(seq))
        print(out[:1500])
print('%d/%d same' % (N - fails, N))

